const stripBase = (path: string) => basePath && path.startsWith(basePath) ? path.slice(basePath.length) || '/' : path;
type MenuCartItem = { product: Product; quantity: number };
const cartKey = (slug: string) => `menupro-cart:${slug}`;
const readCart = (slug: string): MenuCartItem[] => {
  try {
    return JSON.parse(sessionStorage.getItem(cartKey(slug)) ?? '[]') as MenuCartItem[];
  } catch {
    return [];
  }
};
const saveCart = (slug: string, items: MenuCartItem[]) => sessionStorage.setItem(cartKey(slug), JSON.stringify(items));
const clearCart = (slug: string) => sessionStorage.removeItem(cartKey(slug));

