function ErrorState({ message = 'Não conseguimos carregar esses dados.' }: { message?: string }) { return <div className="surface grid min-h-56 place-items-center rounded-2xl p-8 text-center"><div><CircleAlert className="mx-auto mb-3 text-destructive" size={27} /><p className="font-semibold">{message}</p><p className="mt-1 text-sm text-muted-foreground">Tente novamente em alguns instantes.</p></div></div>; }
function EmptyState({ icon: Icon = Package, title, description, action }: { icon?: typeof Package; title: string; description: string; action?: ReactNode }) { return <div className="surface grid min-h-60 place-items-center rounded-2xl p-8 text-center"><div><span className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-primary/10 text-primary"><Icon size={23} /></span><h3 className="font-bold">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm text-muted-foreground">{description}</p>{action && <div className="mt-4">{action}</div>}</div></div>; }
function StatusBadge({ status }: { status: string }) { const labels: Record<string, string> = { new: 'Novo', confirmed: 'Confirmado', preparing: 'Preparando', ready: 'Pronto', delivering: 'A caminho', completed: 'Concluído', cancelled: 'Cancelado', active: 'Ativo', inactive: 'Inativo' }; return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold ${['new', 'ready', 'active'].includes(status) ? 'bg-primary/10 text-primary' : status === 'cancelled' || status === 'inactive' ? 'bg-destructive/10 text-destructive' : 'bg-secondary/10 text-secondary'}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{labels[status] ?? status}</span>; }

