function RequireAuth({ children }: { children: ReactNode }) { const { isLoaded, isSignedIn } = useAuth(); if (!isLoaded) return <div className="grid min-h-[100dvh] place-items-center bg-background"><div className="text-center"><div className="skeleton mx-auto mb-3 h-10 w-10 rounded-xl" /><p className="text-sm text-muted-foreground">Abrindo seu espaço...</p></div></div>; return isSignedIn ? <>{children}</> : <Redirect to="/login" />; }

